  WatchMusicService.Job existing=WatchMusicService.current;if(existing!=null&&existing.identity.equals(input.identity)&&!existing.clean.failed){watchJob=existing;cleanSession=existing.clean;position=player.getCurrentPosition();resume=player.getPlayWhenReady();cleanRequested=true;attachWatch();return;}
  if(WatchMusicService.busy()){toast("انتظر اكتمال المعالجة الحالية أو أوقفها من الإشعار");return;}
  long duration=player.getDuration();if(duration<=0||duration==C.TIME_UNSET){toast("انتظر تحميل المقطع أولًا");return;}
  position=pendingWatchPosition=Math.max(0,Math.min(player.getCurrentPosition(),duration-100));resume=player.getPlayWhenReady();cleanRequested=true;player.setVolume(0);player.pause();showCleanStatus("تجهيز الصوت المنظّف من "+stamp(position),true);musicButton.setText("الصوت المنظّف");
